template <typename T>
T mod_inv(T a, T m) {
  T u = 0, v = 1;
  while (a != 0) {
    T t = m / a;
    m -= t * a; swap(a, m);
    u -= t * v; swap(u, v);
  }
  assert(m == 1);
  return u;
}

template <typename T>
class Mod {
 public:
  using Type = typename decay<decltype(T::value)>::type;

  Mod() : val() {}
  template <typename U>
  Mod(const U& x) {
    val = normalize(x);
  }

  static Type normalize(const U& x) {
    Type v;
    if (-mod() <= x && x < mod()) v = static_cast<Type>(x);
    else v = static_cast<Type>(x % mod());
    if (v < 0) v += mod();
    return v;
  }

  const Type& get() const { return val; }
  explicit operator Type() const { return val; }
  static constexpr Type mod() { return T::value; }

  Mod& operator+=(const Mod& other) {
    if ((val += other.val) >= mod()) val -= mod();
    return *this;
  }
  Mod& operator-=(const Mod& other) {
    if ((val -= other.val) < 0) val += mod();
    return *this;
  }
  template <typename U> Mod& operator+=(const U& other) { return *this += Mod(other); }
  template <typename U> Mod& operator-=(const U& other) { return *this -= Mod(other); }
  Mod& operator++() { return *this += 1; }
  Mod& operator--() { return *this -= 1; }
  Mod operator++(int) { Mod tmp(*this); *this += 1; return tmp; }
  Mod operator--(int) { Mod tmp(*this); *this -= 1; return tmp; }
  Mod operator-() const { return Mod(-val); }

  template <typename U = T>
  typename enable_if<is_same<typename Mod<U>::Type, int>::value, Mod>::type& operator*=(const Mod& rhs) {
#ifdef _WIN32
    uint64_t x = static_cast<int64_t>(val) * static_cast<int64_t>(rhs.val);
    uint32_t xh = static_cast<uint32_t>(x >> 32), xl = static_cast<uint32_t>(x), d, m;
    asm(
      "divl %4; \n\t"
      : "=a" (d), "=d" (m)
      : "d" (xh), "a" (xl), "r" (mod())
    );
    val = m;
#else
    val = normalize(static_cast<int64_t>(val) * static_cast<int64_t>(rhs.val));
#endif
    return *this;
  }
  template <typename U = T>
  typename enable_if<is_same<typename Mod<U>::Type, int64_t>::value, Mod>::type& operator*=(const Mod& rhs) {
    int64_t q = static_cast<int64_t>(static_cast<long double>(val) * rhs.val / mod());
    val = normalize(val * rhs.val - q * mod());
    return *this;
  }
  template <typename U = T>
  typename enable_if<!is_integral<typename Mod<U>::Type>::value, Mod>::type& operator*=(const Mod& rhs) {
    val = normalize(val * rhs.val);
    return *this;
  }

  Mod& operator/=(const Mod& other) { return *this *= mod_inv(other.val, mod()); }

  friend bool operator==(const Mod& lhs, const Mod& rhs) { return lhs.val == rhs.val; }
  friend bool operator<(const Mod& lhs, const Mod& rhs) { return lhs.val < rhs.val; }

  friend std::istream& operator>>(std::istream& in, Mod& num) {
    typename common_type<typename Mod::Type, int64_t>::type x;
    in >> x;
    num.val = Mod::normalize(x);
    return in;
  }

 private:
  Type val;
};

using ModType5 = int;
struct MyMod5 { static ModType5 value; };
ModType5 MyMod5::value;
using Num5 = Mod<MyMod5>;

int main() {
  int n, m;
  cin >> n >> m >> MyMod5::value;
  vector<Num5> fact = {1};
  vector<Num5> inv_fact = {1};
  auto C = [&](int x, int y) {
    int sz = max(x, y);
    while ((int)fact.size() <= sz) {
      fact.push_back(fact.back() * (int)fact.size());
      inv_fact.push_back(1 / fact.back());
    }
    if (y < 0 || y > x) return Num5(0);
    return fact[x] * inv_fact[y] * inv_fact[x - y];
  };
  vector<Num5> ways_arr(m + 1, 0), ways_count(m + 1, 0);
  ways_count[0] = 1;
  for (int i = 1; i <= m; ++i) {
    for (int j = 0; j < i; ++j) {
      int l = j, r = i - 1 - j;
      ways_arr[i] += ways_count[l] * ways_count[r] * C(l + r, l) * Num5(l + r + 2);
    }
    for (int j = 0; j < i; ++j) {
      int l = j, r = i - 1 - j;
      Num5 add = (Num5(l) * (l + 1) + Num5(r) * (r + 1)) / 2;
      ways_count[i] += ways_count[l] * ways_count[r] * C(l + r, l) * add;
    }
  }
  vector<vector<Num5>> dp(n + 1, vector<Num5>(m + 1, 0));
  vector<vector<Num5>> ways_dp(n + 1, vector<Num5>(m + 1, 0));
  ways_dp[0][0] = 1;
  for (int i = 1; i <= n; ++i) {
    for (int s = 0; s <= min(m, i); ++s) {
      if (s == i) {
        dp[i][s] = ways_count[s];
        continue;
      }
      for (int d = 1; d <= s + 1; ++d) {
        Num5 ft = dp[i - d][s + 1 - d];
        Num5 way = ways_dp[i - d][s + 1 - d];
        int add = d - 1;
        ways_dp[i][s] += way * ways_count[add] * C(s, add);
        dp[i][s] += (way * ways_count[add] + ways_dp[i - d][s + 1 - d] * ft) * C(s, add);
      }
    }
  }
  cout << dp[n][m];
  return 0;
}
